import json
from pathlib import Path
repo=Path(__file__).resolve().parents[2];rows=json.loads((repo/'art-sources/Audio/Freesound/manifest.json').read_text(encoding='utf-8'))
lines=['# Audio sources — recorded-source pass, 2026-10-11','','These are candidate sound edits, not a final sound-art approval. Freesound inputs are public HQ MP3 listening previews, not original lossless downloads. A WAV conversion does not restore lost source quality. Each source page explicitly declared CC0 when checked. Source URLs, dates, hashes and edit intervals are in the manifests.','','| Role | Author and source | License |','|---|---|---|']
for r in rows:lines.append(f"| {r['role']} | [{r['author']} — {r['id']}]({r['page']}) | [{r['license']}]({r['license_url']}) |")
lines+=['','Kenney: [Impact Sounds](https://kenney.nl/assets/impact-sounds) and [RPG Audio](https://kenney.nl/assets/rpg-audio), CC0. Original license files remain under `art-sources/Audio/Kenney/`.','','Edits: mono downmix, transient or cycle selection, short edge fades / 80 ms loop crossfade, transient peak target -1 dBFS; long sounds RMS target -20 dBFS constrained by a -3 dBFS peak ceiling; PCM16 at original sample rate. See `art-sources/Audio/processed-manifest.json`. Review all edits by listening before final selection.','','Known substitutions: Western Electric phone is not a verified Soviet telephone; chime comes from a Gustav Becker Westminster recording; wet pasta foley stands in for Guest palm impacts. Finger crack is recorded knuckle foley; wet tear is a short chicken-carcass foley edit; choked cry is an acted adult male pain grunt, not the final Misha actor. Tinnitus is an intentionally synthesized effect, not a field recording. Existing phone and grandmother synthetic speech is unchanged and temporary. No claim of historically exact sound or natural actor performance.']
(repo/'CREDITS-AUDIO.md').write_text('\n'.join(lines)+'\n',encoding='utf-8')